class Solution:
    def countWays(self, ranges: list[list[int]]) -> int:
        MOD = 1_000_000_007
        n = len(ranges)
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                a, b = ranges[i]
                c, d = ranges[j]
                if max(a, c) <= min(b, d):
                    graph[i].append(j)
                    graph[j].append(i)
        seen = [False] * n
        groups = 0
        for i in range(n):
            if not seen[i]:
                groups += 1
                stack = [i]
                seen[i] = True
                while stack:
                    u = stack.pop()
                    for v in graph[u]:
                        if not seen[v]:
                            seen[v] = True
                            stack.append(v)
        return pow(2, groups, MOD)

