class Solution:
    def countWays(self, ranges: list[list[int]]) -> int:
        MOD = 1_000_000_007
        ranges = sorted(ranges)
        groups = 0
        cur_end = -1
        for s, e in ranges:
            if s > cur_end:
                groups += 1
                cur_end = e
            else:
                cur_end = max(cur_end, e)
        return pow(2, groups, MOD)

